// @vitest-environment jsdom
import { describe, it, expect, vi, afterEach } from 'vitest'
import { EditorView } from '@codemirror/view'
import { EditorState } from '@codemirror/state'
import { startCompletion, currentCompletions, acceptCompletion, completionStatus } from '@codemirror/autocomplete'
import type { FileEntry } from '@/types/models'
import { useFileTreeStore } from '@/stores/fileTreeStore'

const { listDirectoryMock, getSessionWorkspaceMock } = vi.hoisted(() => ({
  listDirectoryMock: vi.fn(),
  getSessionWorkspaceMock: vi.fn(),
}))
vi.mock('@/api/workspace', () => ({
  listDirectory: (...args: unknown[]) => listDirectoryMock(...args),
  getSessionWorkspace: (...args: unknown[]) => getSessionWorkspaceMock(...args),
}))
vi.mock('@/api/skills', () => ({ listSkills: vi.fn().mockResolvedValue([]) }))
vi.mock('@/api/agents', () => ({ listAgents: vi.fn().mockResolvedValue([]) }))
vi.mock('@/api/runtime', () => ({ subscribe: vi.fn(() => () => {}) }))
vi.mock('@/lib/logger', () => ({ logger: { error: vi.fn(), warn: vi.fn(), info: vi.fn(), debug: vi.fn() } }))

import { createChatAutocomplete } from '/Users/vkochetkov/Repositories/c0wrk/frontend/src/lib/cmChatAutocomplete'

describe('debug', () => {
  afterEach(() => { vi.clearAllMocks(); useFileTreeStore.setState({ rootPath: '' }) })
  it('applies', async () => {
    useFileTreeStore.setState({ rootPath: '/ws' })
    listDirectoryMock.mockResolvedValue([{ name: 'my file.txt', path: '/ws/my file.txt', is_dir: false } as FileEntry])
    const host = document.createElement('div')
    document.body.appendChild(host)
    const view = new EditorView({
      state: EditorState.create({ doc: '', extensions: [createChatAutocomplete()] }),
      parent: host,
    })
    view.dispatch(view.state.replaceSelection("@'my fil"))
    startCompletion(view)
    await new Promise((r) => setTimeout(r, 300))
    // eslint-disable-next-line no-console
    console.log('status:', completionStatus(view.state), 'options:', JSON.stringify(currentCompletions(view.state).map((c) => ({ label: c.label, apply: c.apply }))))
    const ok = acceptCompletion(view)
    // eslint-disable-next-line no-console
    console.log('accept returned', ok, 'doc:', JSON.stringify(view.state.doc.toString()))
    view.destroy(); host.remove()
    expect(true).toBe(true)
  })
})
